spec.setup_code:
var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

var margin = 40;
                return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var originX = margin, originY = H - margin;
                    var axisW = W - 2 * margin, axisH = H - 2 * margin;
                    ctx.strokeStyle = '#333333';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(originX, originY);
                    ctx.lineTo(originX + axisW, originY);
                    ctx.moveTo(originX, originY);
                    ctx.lineTo(originX, originY - axisH);
                    ctx.stroke();
                    var x1 = originX + axisW * 0.2, y1 = originY - axisH * 0.2;
                    var x2 = originX + axisW * 0.8, y2 = originY - axisH * 0.8;
                    ctx.strokeStyle = '#4A90D9';
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(x1, y1);
                    ctx.lineTo(x2, y2);
                    ctx.stroke();
                    var frac = (Math.sin(t * 0.03) + 1) / 2;
                    var runX = x1 + (x2 - x1) * frac;
                    ctx.strokeStyle = '#E8593C';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(x1, y1);
                    ctx.lineTo(runX, y1);
                    ctx.lineTo(runX, y1 - (y1 - (y1 + (y2 - y1) * frac)));
                    ctx.stroke();
                    var riseY = y1 + (y2 - y1) * frac;
                    ctx.beginPath();
                    ctx.moveTo(runX, y1);
                    ctx.lineTo(runX, riseY);
                    ctx.stroke();
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(runX, riseY, 5, 0, Math.PI * 2);
                    ctx.fill();
                  }
                };
